/* Original practice materials for the two-week plan. */
(() => {
  "use strict";
  const question = (q, options, correct, why) => ({q, options, correct, why});
  const exercise = (title, text, ...questions) => ({title, text, questions});
  const day = (topic, title, reading, listening, phrase, example) => ({
    topic, title, reading, listening, transfer: {phrase, example}
  });

  window.SCW_DAYS = [
    day("University", "认识校园 / Finding your feet",
      exercise("A different route through induction",
        "During induction week, a volunteer took twelve new students to eight campus buildings. By the end, several could recognise the library but could not explain how to borrow a book. The next morning she tried a different route with another group. They visited only three places. At each stop, someone had to complete a small task, such as finding the returns desk or locating the timetable for a sports class. Both tours took about forty minutes. At lunch the second group could describe what they would do on a return visit. The volunteer decided to keep the shorter route for the next tour. She also noted that the groups had different students, so she could not tell whether the route alone explained the difference.",
        question("What changed most on the second tour?", ["Students completed practical tasks at fewer stops.", "Students had more time to walk between buildings.", "All the buildings were chosen by the students."], 0, "第二次参观只有三站，每站都有任务。 The second group visited three places and did something at each."),
        question("What does ‘the difference’ in the final sentence refer to?", ["The cost of running each tour", "How well students could explain a future visit", "The distance between the first and last buildings"], 1, "第二组能说明下次去会怎么做。 It refers to what each group could explain afterwards."),
        question("Why is the volunteer careful about her conclusion?", ["The second tour was cancelled halfway through.", "The volunteers forgot to record the length of each tour.", "Different groups of students took the tours."], 2, "两组成员不同，路线只是可能原因。 Different participants provide another possible explanation.")),
      exercise("An unexpected change of meeting point",
        "Hi everyone, this is a quick update about Saturday's campus walk. We had planned to meet by the main library doors at ten. A book fair is using that entrance, so please wait beside the clock outside the sports centre instead. The start time is still ten. Bring the small campus map from your welcome pack if you have it. We'll use it in pairs, so there is no need for everyone to bring a copy. If you arrive after we have left, go straight to the student services desk. That's our first stop.",
        question("Where should students meet at ten?", ["At the student services desk", "Outside the sports centre", "Inside the library entrance"], 1, "新集合点是体育中心外的钟旁。 The clock by the sports centre is the revised meeting point."),
        question("Why is one map per student unnecessary?", ["Maps are now displayed at every stop.", "The organiser is reading the route aloud.", "Students will share maps in pairs."], 2, "通知说两人共用。 The group will work with maps in pairs."),
        question("What should a late student do?", ["Go to the first stop on the walk.", "Wait until the book fair closes.", "Join the group at the final stop."], 0, "第一站是学生服务台。 Late arrivals should catch up at the student services desk.")),
      "get familiar with", "I got familiar with the campus by finding the rooms I would actually use."),

    day("Communication", "把要求说清楚 / Making requests clear",
      exercise("The slide nobody changed",
        "On Monday, a project leader left a comment beside a crowded slide. She wrote that the group should take another look at it. One teammate read the slide carefully and replied that its figures were correct. Another assumed that a designer would replace the whole chart. At Thursday's rehearsal, the chart was still too small for people at the back to read. The leader then named the result she wanted and the person responsible. She asked Leila to enlarge the labels and send a new version by six. Leila finished in ten minutes. In her reflection, the leader wrote that her first comment had expressed concern, but had left the next action open to several reasonable interpretations.",
        question("Why did the slide remain hard to read?", ["The figures had been calculated incorrectly.", "Leila had missed the Monday meeting.", "The original comment did not specify a change."], 2, "大家把“再看看”理解成不同任务。 The first request allowed several interpretations."),
        question("Which description best matches the second request?", ["It identified a person, an action and a deadline.", "It gave the entire group a new design project.", "It asked for another check of the figures."], 0, "指定 Leila 放大标签，并在六点前发回。 It named Leila, the change and the delivery time."),
        question("What can be inferred about the first teammate?", ["They were responsible for the visual design.", "They had a plausible interpretation of the comment.", "They did not read the comment until Thursday."], 1, "核对数据是“再看一遍”的合理理解之一。 Checking accuracy was one reasonable reading.")),
      exercise("Feedback on a practice talk",
        "I heard your practice talk this morning. Your opening question made me curious, and the story about the missed bus was easy to follow. I lost track when you started comparing the two surveys. You mentioned a percentage before saying what the students had been asked. Could you introduce that question first, then give one figure from each survey? You can leave out the smaller details because we already have the table on the handout. Try the comparison again tomorrow. I'll tell you what I think the two figures show.",
        question("When did the listener lose track?", ["During the comparison of two surveys", "At the opening question", "During the story about a bus"], 0, "两项调查的比较导致困惑。 The comparison is explicitly identified as the difficult part."),
        question("What change is requested first?", ["Replace the handout with a new chart.", "Explain what the survey question was.", "Remove all the figures from the talk."], 1, "先交代问题，再报数字。 The listener wants the question introduced before the percentages."),
        question("How will the speaker know whether the revision works?", ["The revised talk will be longer.", "The listener will calculate the survey results.", "The listener will explain the meaning of the figures."], 2, "听者将复述数据说明了什么。 Their interpretation will reveal whether the comparison is clear.")),
      "make a request more specific", "Naming the deadline made my request more specific, so my teammate knew when I needed the file."),

    day("Health", "寻找可坚持的习惯 / Building a realistic habit",
      exercise("What a step count left out",
        "For a class project, Nia compared the weekly activity totals shown by her watch. The result surprised her. One week contained fewer steps even though she had spent two evenings swimming. Her watch had stayed in her locker during both sessions. She reopened her diary and added the activities she could remember. This changed the question she wanted her project to answer. Instead of deciding which week had been healthier, she examined which activities a step count represented well. Walking to class appeared clearly in the numbers. Swimming and time spent stretching did not. In her final slide, Nia placed a short diary entry beside the graph so her audience could understand why two records of the same week told different stories.",
        question("Why were the step totals lower than Nia expected?", ["The watch was broken all week.", "Her swimming sessions were absent from the record.", "She had stopped walking to class."], 1, "游泳时手表留在储物柜里。 Her watch stayed in her locker during the swims."),
        question("What did Nia eventually investigate?", ["Which activity burns the most energy", "How to increase the number of swimming sessions", "Which activities are captured by a step count"], 2, "她把项目改为研究指标的覆盖范围。 Her revised question concerns what the measure captures."),
        question("What was the purpose of the diary entry on the slide?", ["To explain an apparent gap in the graph", "To replace the weekly totals completely", "To show that stretching produces more steps"], 0, "日记为图中缺失的活动提供背景。 The diary provides context for activity the graph missed.")),
      exercise("An appointment for a short walk",
        "My friend and I tried going for a run before our first lecture, but after two mornings neither of us wanted to get up early. This week we changed the plan. On the days we eat lunch together, we take the long route back to the library. It adds about eight minutes and we can talk while we walk. We don't try to make up for a missed day. Our aim for now is to find a routine we can keep during a busy week. Next Friday we'll decide whether lunchtime is still convenient.",
        question("Why did the friends change their original plan?", ["The library closed early.", "They needed to train for an event.", "Getting up early was difficult to maintain."], 2, "早起跑步两天后就难以坚持。 The early start made the first routine hard to keep."),
        question("What makes the new plan practical?", ["It fits a journey they already make after lunch.", "It can be done at any time without a partner.", "It replaces their afternoon classes."], 0, "他们在本来就要走的返程上增加八分钟。 The walk extends their usual route back."),
        question("What will the friends review on Friday?", ["How fast they can complete a run", "Whether the time fits their routine", "How to recover every missed day"], 1, "他们要看午间是否仍然方便。 The review concerns whether lunchtime still works.")),
      "fit a habit into my routine", "I can fit a short walk into my routine by walking one more stop after lunch."),

    day("Jobs", "沟通工作需求 / Understanding workplace needs",
      exercise("A desk for the task",
        "A small design company offered its staff a choice of desks during a busy month. Some desks stood in an open room where colleagues could speak easily. Others were in a quieter room down the hall. At first the manager expected each employee to choose a permanent place. However, booking records showed that several people moved between the rooms during the same week. One designer explained why. On Monday she needed quick answers from colleagues while checking a client's brief. On Wednesday she needed an uninterrupted hour to write a proposal. Her preference followed the task rather than a fixed personal habit. When the company renewed the trial, it allowed staff to reserve desks for half a day at a time.",
        question("What surprised the manager?", ["Several employees used both rooms in a single week.", "The quiet room had no available desks.", "Everyone wanted the same permanent desk."], 0, "他原以为大家会固定选位。 He expected fixed choices, but the records showed movement."),
        question("Why did the designer prefer the open room on Monday?", ["She needed to write a proposal alone.", "She needed quick answers about a brief.", "She wanted to meet the client in person."], 1, "周一的工作需要随时问同事。 Her Monday task required quick exchanges with colleagues."),
        question("Which policy best reflects what the company learned?", ["Assign one room to each department.", "Close the open room during busy weeks.", "Let employees choose space for shorter periods."], 2, "半天预约允许同一人按任务换空间。 Half-day bookings accommodate changing tasks.")),
      exercise("Two roles at the careers fair",
        "Thanks for offering to help at the careers fair. At first we needed two people at the welcome table, but the organiser has found another volunteer. Could you look after the interview room instead? You'll check the list outside and show each student to the right chair. You won't be judging the interviews. If someone arrives without a booking, ask them to speak to the welcome team rather than adding their name yourself. Please arrive at half past one. The first interview starts fifteen minutes later, and I'd like time to show you the room.",
        question("What is the listener's new main job?", ["Assess applicants during interviews.", "Guide booked students into the interview room.", "Recruit another person for the welcome team."], 1, "新任务是引导有预约的学生入座。 The listener will check the list and show students where to sit."),
        question("What should an unbooked student do?", ["Wait in an interview chair.", "Add their own name to the list.", "Speak to the welcome team."], 2, "未预约的学生要找接待组。 The speaker directs unbooked visitors to the welcome team."),
        question("When is the first interview?", ["At 1:45", "At 1:15", "At 1:30"], 0, "一点半到场，十五分钟后面试。 Fifteen minutes after half past one is 1:45.")),
      "depend on the task", "Whether I prefer a shared office depends on the task I need to finish."),

    day("People", "评价建议的来源 / Weighing up advice",
      exercise("A popular face at the open day",
        "When a well-known singer visited a community music school, photographs from the event attracted many visitors to its website. Few of those visitors completed the application form for free weekend lessons. A volunteer called three families who had started an application and left it unfinished. The families had questions about travel costs and whether beginners needed an instrument. The school then put the answers next to the form and included a telephone number. The singer shared the updated page at her next concert. This time the volunteer counted completed applications as well as website visits. She wanted to understand two different stages of the event. Public attention brought families to the page, while practical information helped them decide whether they could take part.",
        question("What was the main difficulty after the first visit?", ["The singer refused to mention the school.", "The school had no weekend places available.", "Many visitors left before completing an application."], 2, "网页有人气，但填完的申请少。 The page attracted interest that did not turn into many applications."),
        question("Why were answers about travel and instruments added?", ["They addressed practical worries raised by families.", "They explained why the concert had been cancelled.", "They showed that all applicants had musical experience."], 0, "未完成申请的家庭提出了这两类顾虑。 These were the questions that had held families back."),
        question("Why count both visits and finished applications?", ["To decide how many volunteers the concert needs", "To distinguish attention from actual participation decisions", "To find out which instruments are most popular"], 1, "两项数字对应看见信息和决定报名两个阶段。 The figures describe two different stages.")),
      exercise("Choosing a guest for a student podcast",
        "We could invite the runner with a large online following, but first we should decide what the episode is about. If we're discussing how to prepare for a first race, her experience would give beginners something useful to hear. If the question is how the local running club spends its membership fees, its treasurer would be a better guest. I suggest we make this week's episode about race preparation and ask the runner for one specific training story. Then we can invite the treasurer for a separate episode when we have the club's annual report.",
        question("What should guide the choice of guest?", ["The question the episode will address", "The number of people in the running club", "Whether the guest charges a fee"], 0, "先定节目主题，再看谁有相关经验。 The host matches the guest's experience to the question."),
        question("What does the speaker want from the runner?", ["A copy of the club's accounts", "One concrete story about training", "A list of club members"], 1, "主持人要求一段具体训练故事。 The runner is asked for a specific training story."),
        question("Why will the treasurer appear later?", ["The treasurer has never run a race.", "Listeners have already heard the finance episode.", "The annual report will support the later discussion."], 2, "之后可以结合年度报告谈经费。 The report will provide material for the finance episode.")),
      "have experience in", "I listen to someone who has experience in the area I am asking about."),

    day("Environment", "判断回收方案 / Testing a recycling scheme",
      exercise("Where the cups ended up",
        "To prepare a proposal about waste, a student team observed two bins beside a campus café. Above the first bin, a sign showed a green leaf. Above the second, a sign listed several materials in small print. During the lunch rush, students often looked at the signs briefly and dropped everything into whichever bin was closer. The team suggested showing photographs of cups, lids and leftover drinks beside the correct openings. However, the café manager raised a further question. Even well-sorted cups would be wasted if the company collecting them could not process their lining. Before ordering new signs, the team agreed to check which cups the local collector accepted. That information would determine what their photographs should tell customers to do.",
        question("What did the observers notice at lunchtime?", ["Students read both signs very carefully.", "Convenience often affected which bin people chose.", "The bins were too far from the café."], 1, "赶时间时，大家常选更近的桶。 Students tended to use whichever bin was closer."),
        question("Why did the manager ask about the cups' lining?", ["It might change the price of drinks.", "It made the pictures harder to print.", "The collection company might be unable to process it."], 2, "分类正确也要后端能处理。 The collector's equipment may not accept that material."),
        question("What will the team do before designing the signs?", ["Check local collection rules.", "Move the café to a quieter site.", "Replace photographs with longer instructions."], 0, "先弄清收运方接受哪些杯子。 They need to verify which cups the collector accepts.")),
      exercise("An announcement before the repair session",
        "Welcome to the student repair session. If you have brought a torn bag or a loose button, please take a seat at the long table by the window. The volunteers there will show you a simple repair and then let you practise it yourself. We have thread and needles, so you only need the item you want to repair. We cannot accept electrical items at this session. If you brought one, take the information sheet by the door. It lists other local services that may be able to help.",
        question("What should students with a torn bag bring?", ["Their own needles", "A printed information sheet", "The item they want to repair"], 2, "线和针由活动提供。 The session supplies the tools, so students bring the damaged item."),
        question("How will students learn the repair?", ["They will watch a demonstration and then try it.", "They will read a list of shops.", "They will leave the item for a volunteer to finish later."], 0, "志愿者演示后，学生自己动手。 The repair is demonstrated and then practised."),
        question("Why is the information sheet useful?", ["It records attendance at the long table.", "It gives other options for electrical repairs.", "It explains how to sew on a button."], 1, "电器不在本次活动范围，清单给出其他渠道。 It directs people with electrical items to other services.")),
      "check what the local service accepts", "Before putting a cup in a recycling bin, I would check what the local service accepts."),

    day("Technology", "分辨功能与权限 / Choosing useful permissions",
      exercise("A digital map with two settings",
        "A campus team designed a digital map for visitors. One setting showed nearby buildings using the phone's current location. The other let visitors type a building name and follow a route from a starting point they selected. A trial user wanted help finding a lecture hall but preferred to keep location sharing switched off. At first she thought the map would stop working completely. When a designer showed her the search setting, she found the hall without sharing her location. The team changed the welcome screen after the trial. It explained what each setting did before asking for permission. The change gave visitors a clearer choice and helped them see which feature required access to the phone's location.",
        question("What was the trial user's initial belief?", ["The map would be unusable with location sharing off.", "All campus buildings had the same name.", "The map could only be used on a laptop."], 0, "她起初以为关闭位置共享会使地图完全不能用。 She thought the whole map depended on sharing location."),
        question("How did she find the lecture hall?", ["She gave the designer her phone password.", "She searched by name and chose a starting point.", "She asked another visitor to share a route."], 1, "手动搜索功能不需要当前位置。 She used the setting with a manually selected start."),
        question("What is the main purpose of the new welcome screen?", ["To require every visitor to turn on location sharing", "To limit visitors to one building", "To explain what permission each feature needs"], 2, "新页面先说明功能，再询问权限。 Visitors can see the connection between a feature and its permission.")),
      exercise("A reminder during a busy project",
        "I used to mute every message while I was writing a report. That worked until I missed a note saying our group meeting had moved to another room. Now I set a focus period of forty minutes and allow messages from the project organiser to come through. When the timer ends, I check the group chat once and then start the next section. This arrangement is useful when a decision might affect the whole team. If I am working on an individual assignment with no meeting planned, I still prefer to silence everything until the break.",
        question("What problem did the speaker experience?", ["A report was shared with the wrong person.", "A room-change message was missed.", "The meeting organiser forgot to set a timer."], 1, "把所有消息静音后，没看到换教室的通知。 Muting everything hid the room update."),
        question("Whose messages can interrupt a focus period?", ["Anyone in a class group", "The speaker's family only", "The project organiser's"], 2, "团队项目中保留了组织者的消息。 The organiser is the stated exception."),
        question("When does the speaker still silence all messages?", ["During individual work with no meeting planned", "While the group is choosing a new room", "During every forty-minute team discussion"], 0, "独立作业且没有会议时仍全部静音。 The final sentence gives this condition.")),
      "give users a clear choice", "Apps should give users a clear choice about sharing the information a feature needs."),

    day("Education", "从记住到解释 / Explaining what you know",
      exercise("The practice question that changed a revision plan",
        "Mei felt ready for her economics quiz because she could recognise every term on her revision cards. Then her classmate turned a card over and asked her to explain the idea without looking. Mei could give the first sentence of the definition, but she could not think of an example. They changed the way they used the cards. On the back of each one, Mei wrote a short situation in which the idea might be useful. Two days later her classmate asked about a different situation involving the same idea. This time Mei explained her answer in her own words. She kept a separate pile for cards she could recognise but could not yet apply to a new case.",
        question("What did Mei's first practice answer reveal?", ["She had revised the wrong subject.", "She could explain every card without a cue.", "Recognition did not guarantee she could apply an idea."], 2, "她认识术语，却想不出例子。 Knowing the term did not give her an example."),
        question("Why did her classmate use a different situation two days later?", ["To see whether Mei could apply the same idea elsewhere", "To introduce a term outside the quiz", "To check whether Mei had copied the original example exactly"], 0, "换情境能检验迁移。 A fresh case tests whether the idea can transfer."),
        question("Which card belongs in Mei's separate pile?", ["A term she can use in several new situations", "A familiar term she cannot use in a new case", "An empty card waiting for a new question"], 1, "单独留出的是“认识但不会应用”的卡。 The pile is for recognised ideas she cannot yet apply.")),
      exercise("Booking a study room before the test",
        "Mina, I've checked the study room bookings for Wednesday. The big room is free at four, but there will only be three of us, so I've booked the smaller room at half past three. Let's use the first twenty minutes for individual practice. Then each person can explain one answer the others found difficult. Please bring one question you got wrong this week and the notes that helped you correct it. If the discussion finishes early, we can use the extra time to try a similar question without looking at those notes.",
        question("Which room has been booked?", ["The smaller room at 3:30", "The large room at 4:00", "The small room at 4:30"], 0, "四点的大房间只是可选项。 The booking is for the smaller room at half past three."),
        question("What will happen first?", ["Everyone will explain a corrected answer.", "Each student will practise individually.", "The students will compare notes from the last meeting."], 1, "前二十分钟独立做题。 The first twenty minutes are for individual work."),
        question("What is the plan if time remains?", ["Move to the larger room.", "Write questions for the next test.", "Try a related question without notes."], 2, "空余时间做同类题，且不看笔记。 The extra task checks independent application.")),
      "apply an idea to a new case", "I know I understand a method when I can apply it to a new case."),

    day("Places", "从细节描述地点 / Describing a place through detail",
      exercise("The bench that faced the path",
        "A student guide used to describe a riverside park by listing its size, the number of entrances and the names of its trees. During a walk with an older visitor, she noticed a detail that was missing from her description. Some benches faced the water, while others faced the main path. The visitor chose a bench by the path because he wanted to watch people passing and greet a neighbour. Another visitor selected a seat by the water to read. Both people valued the park, but the same view would not have suited them equally well. For her next tour, the guide planned to ask visitors how they wanted to spend their time before recommending a place to sit.",
        question("What was missing from the guide's earlier description?", ["The official name of the park", "How a feature could serve different visitor needs", "A list of every available entrance"], 1, "原来只列事实，忽略不同使用需求。 The bench choices show how people use the space differently."),
        question("Why did the older visitor choose the path?", ["It was the shortest route home.", "It had the only seat in the shade.", "It offered a chance to see and greet people."], 2, "他想看行人并和邻居打招呼。 The social opportunity mattered to him."),
        question("How will the guide change her next tour?", ["Ask about visitors' plans before making a suggestion.", "Recommend the waterfront seats to every visitor.", "Stop mentioning benches during the tour."], 0, "她会先问游客想做什么。 Her advice will follow the visitor's preferred activity.")),
      exercise("A change to the walking route",
        "For this afternoon's walk, we'll start at the museum and finish by the canal. The small bridge on our usual route is closed, so after the museum we'll follow the wider road for one block and turn into a quieter lane. The new route is about ten minutes longer. If you need to leave before the final stop, there is a bus stop beside the market halfway along the walk. The forecast suggests rain, but that isn't the reason for the change. We've chosen this route because the bridge is being repaired.",
        question("What caused the route change?", ["A bus service was cancelled.", "Heavy rain had already started.", "The usual bridge is being repaired."], 2, "改道原因是修桥。 The speaker explicitly distinguishes repairs from the rain forecast."),
        question("Where can someone leave the walk early?", ["Beside the market", "At the closed bridge", "At a bus stop beyond the canal"], 0, "市场旁有公交站。 The bus stop by the market is halfway along the walk."),
        question("How does the new route compare with the usual one?", ["It misses the museum.", "It takes about ten extra minutes.", "It finishes in the quiet lane."], 1, "新路线多花约十分钟。 The destination stays by the canal, with a longer journey.")),
      "suit different needs", "Benches beside a busy path and seats by the water suit different needs."),

    day("Change", "看懂变化的代价 / Weighing a change",
      exercise("A timetable with one missing connection",
        "A transport club welcomed a new evening train because it left the city centre later than the old service. On the first Friday, several members used it after a concert. The train reached their local station on time, but the last connecting bus had already left. For passengers living near the station, the new timetable offered a useful extra hour in the city. For those living farther away, the last part of the journey became more difficult. The club wrote to the bus operator with the train's arrival time and the bus departure time and asked whether a later connection would be possible on Fridays. Its letter described a problem with the whole journey even though the train itself had run exactly as planned.",
        question("Which group benefited most immediately?", ["Passengers who lived near the station", "Passengers who depended on the last bus", "Passengers who needed to return before the concert"], 0, "住得近的人不用接驳。 Nearby passengers gained the later departure without losing a connection."),
        question("What evidence did the club send?", ["The price of concert tickets", "Details showing how the two services were timed", "A count of all passengers living in the city"], 1, "信中列出两项时间信息，说明衔接问题。 The timing information shows the connection difficulty."),
        question("Which conclusion best fits the text?", ["A later train is always worse for neighbouring areas.", "The train arrived later than its schedule.", "A useful service change can depend on another service."], 2, "新列车的价值取决于后续接驳。 The effect depends on the passenger's onward transport.")),
      exercise("The revised cycle route",
        "Our usual cycle route to campus passes through the main square. From Monday there will be an outdoor exhibition there, so cyclists will need to leave their bikes at the entrance or use a different route. I tried the alternative yesterday. It turns left at the post office, follows the river and reaches the east gate in about twelve minutes. That's three minutes longer than my usual ride. I prefer it when I'm carrying a laptop because there are fewer sudden stops. When the exhibition ends, we can decide which route suits us on a normal day.",
        question("Which change starts on Monday?", ["The east gate will close permanently.", "Cyclists will have to walk every part of the river route.", "An exhibition will affect cycling through the main square."], 2, "展览将占用广场。 The exhibition changes how cyclists can use the square."),
        question("How long is the speaker's usual ride?", ["About nine minutes", "About twelve minutes", "About fifteen minutes"], 0, "新线路十二分钟，比原来多三分钟。 Twelve minus three gives nine."),
        question("Why does the speaker like the alternative with a laptop?", ["It is shorter than the usual route.", "There are fewer abrupt stops.", "Bikes can be left at the post office."], 1, "少急停是携电脑时偏好的原因。 The speaker values a smoother ride.")),
      "look at the whole journey", "A later train sounds convenient, but we need to look at the whole journey, including the final bus."),

    day("University", "解释规则的理由 / Explaining a campus policy",
      exercise("When an empty study room is still booked",
        "The library team received complaints about study rooms that appeared fully booked online but stayed empty in the evening. Some students reserved a room before they knew whether their group could meet. Others finished early and forgot to cancel the rest of the booking. A proposal to shorten every booking seemed simple. However, a group preparing a long presentation pointed out that this would interrupt meetings that genuinely needed the full hour. The library chose a different trial. Students would check in shortly after their booking began and could release unused time through the same screen. After two weeks, staff planned to compare the time rooms stood empty with the number of groups who reported being interrupted during useful work.",
        question("What were two reasons for rooms standing empty?", ["Students disliked working in the evening and preferred short presentations.", "Some groups never met, and others left early without releasing time.", "The online booking system had stopped accepting new names."], 1, "有人约不成，有人提前离开。 Both situations left formally reserved time unused."),
        question("Why was shortening every booking questioned?", ["Long meetings sometimes needed the full hour.", "Students had requested a higher booking fee.", "The team could not change the digital screen."], 0, "统一缩短会打断确有需要的讨论。 The group explained the cost to legitimate longer sessions."),
        question("What do the two proposed measures allow staff to assess?", ["Whether the room screens look modern", "Which presentation receives the best grade", "Whether room use improves without disrupting useful meetings"], 2, "同时关注空置时长和被打断的工作。 The two measures capture efficiency and disruption.")),
      exercise("What to bring to an academic appointment",
        "You asked about tomorrow's meeting with the academic tutor. Please bring a paragraph you have already tried to write, even if you think it needs a lot of work. The tutor can give more specific advice when there is a real example to discuss. You can also bring the question sheet, but there is no need to print the entire reading pack. We only have twenty minutes, so choose one issue you want to understand better. The tutor will ask you to explain that issue first and then look at the paragraph with you.",
        question("Which item is most important to bring?", ["A printed copy of the whole reading pack", "A completed assignment with all errors corrected", "A paragraph the student has already drafted"], 2, "导师想基于真实草稿给建议。 Even an imperfect paragraph offers something concrete to discuss."),
        question("Why should the student choose one issue?", ["The available meeting time is limited.", "Only one topic is allowed in the course.", "The tutor has already read all the other questions."], 0, "会面只有二十分钟。 Choosing one issue makes the short appointment manageable."),
        question("What will happen before the paragraph is examined?", ["The tutor will print the reading pack.", "The student will explain their chosen issue.", "The student will write a new paragraph."], 1, "先解释问题，再共同看段落。 This order is stated at the end.")),
      "use resources more fairly", "Checking in for a booking could help students use shared study rooms more fairly."),

    day("Communication", "听出话外之意 / Checking an interpretation",
      exercise("What did the pause mean?",
        "During a small-group discussion, Kai suggested changing the order of a presentation. Nobody replied for several seconds. He took the silence as disagreement and quickly withdrew his suggestion. Later, one teammate told him that she had been looking for the original outline on her laptop so she could compare the two versions. Another had wanted to hear an example before choosing. Their silence had not given Kai enough information to know what either person thought. At the next meeting, he tried a more specific follow-up. He asked which section the audience would need to hear first and gave everyone a minute to check the outline. The group then discussed the proposed change using the same document.",
        question("What did Kai initially assume?", ["His teammates disagreed with his idea.", "The outline had been deleted.", "Everyone understood the new order immediately."], 0, "他把沉默当成反对。 He withdrew the proposal because he interpreted the pause as disagreement."),
        question("What connects the teammates' later explanations?", ["Both had already decided to reject the change.", "Both wanted to replace the entire presentation.", "Each needed more information before responding."], 2, "一个找提纲，一个想听例子。 Both explanations involve checking or seeking information."),
        question("How did Kai's follow-up help the second discussion?", ["It asked teammates to vote before reading.", "It provided a specific question and a shared reference.", "It let him decide the order without consulting others."], 1, "更明确的问题和共同文档让大家能具体讨论。 The group had a clear decision and the same outline.")),
      exercise("Clarifying a discussion question",
        "Student: Could I check what you mean by a useful skill? Are you asking us to pick the skill that helps us get our first job, or one that remains useful across different jobs? Those could lead to different answers.\nTutor: For today's discussion, focus on a skill you could use in more than one role. Give a reason and a concrete example. You can talk about your first job if it helps illustrate the point, but that should be an example supporting your wider choice. You'll have a minute to compare ideas with your partner before we hear your answers.",
        question("What distinction does the student ask about?", ["University courses versus paid training", "Getting a first job versus usefulness across different jobs", "Working alone versus working with classmates"], 1, "学生询问的是首次求职与跨职业适用性的区别。 The two interpretations would lead to different choices."),
        question("Which answer would fit the tutor's focus best?", ["A list of the first jobs students hope to get", "A description of the pay in one industry", "One transferable skill with a reason and an example"], 2, "导师要求跨岗位可用的技能、理由和例子。 The wider choice should be supported concretely."),
        question("What happens before the class hears the answers?", ["Students compare ideas with a partner.", "Everyone completes a written exam.", "The tutor chooses a job for each student."], 0, "先进行一分钟同伴交流。 The partner discussion comes before the class answers.")),
      "check what someone means", "If a question has two possible meanings, I can check what the speaker means before answering."),

    day("Environment", "把意见建立在证据上 / Supporting a proposal",
      exercise("Ordering fewer copies",
        "The organisers of a student festival wanted to reduce paper waste. Last year they printed a programme for every person who registered online. At the end of the festival, several unopened boxes remained. This year one organiser suggested offering only a digital programme. A volunteer who welcomed visitors raised a concern. Some people arrived with little battery power, and others liked being able to mark a route on paper. The team agreed to print a smaller number and put a question about paper copies on the registration form. They would also leave a few copies at the entrance for people who had not registered. After the festival, counting unused copies and requests they could not meet would help them plan the next order.",
        question("Why did the team reconsider its printing policy?", ["Visitors asked for a longer programme.", "Digital registration had been cancelled.", "The previous order produced unused boxes of programmes."], 2, "上次活动留下数箱未开封的节目单。 The leftover stock prompted the review."),
        question("Which trade-off does the volunteer identify?", ["Reducing waste while keeping information accessible", "Selling tickets while paying performers", "Designing a logo while updating an app"], 0, "完全电子化可能让部分游客不方便。 Some visitors still need or prefer a paper copy."),
        question("Why count unfulfilled requests as well as unused copies?", ["To determine how long visitors stayed", "To detect both shortages and surplus", "To replace registration with a manual count"], 1, "未满足需求反映印少了，剩余反映印多了。 The two counts identify opposite ordering errors.")),
      exercise("Collecting evidence about noise",
        "Before we recommend any changes to the street outside our building, let's describe the noise more carefully. I stood by the corner for ten minutes yesterday evening and heard several delivery vehicles. That's one useful observation, but it was just after a nearby shop closed. We should return at lunchtime and on a different evening to see whether the same thing happens. While we're there, let's note what people are doing. If walkers can talk comfortably at lunch but have to stop speaking when deliveries arrive, we can explain the effect with a specific example.",
        question("What limits yesterday's observation?", ["It covered a short period just after a shop closed.", "The observer did not know where the corner was.", "No vehicles were seen or heard."], 0, "观察只有十分钟，而且有商店刚打烊这一背景。 The observation may describe a particular moment."),
        question("What does the speaker propose next?", ["Immediately close the street to all traffic.", "Observe the location at other times.", "Only interview people who drive delivery vehicles."], 1, "计划中午和另一个傍晚再看。 Different times can test whether the pattern repeats."),
        question("What would make the proposal more concrete?", ["Giving the street a new name", "Listing every product sold by the shop", "Showing how the noise affects an ordinary conversation"], 2, "路人是否需要停下说话是可观察后果。 An interruption to conversation illustrates the effect.")),
      "support a proposal with evidence", "We could support our proposal with evidence about where and when people actually use the bins."),

    day("Education", "衡量进步 / Judging progress",
      exercise("What changed between the two talks?",
        "For her final practice, Hana compared two recordings made a week apart. The first was a talk about a group assignment. The second covered a different topic, a place she enjoyed visiting. She sounded more relaxed in the second recording, but she was careful about explaining the difference. The place was familiar and the first task had required her to explain a disagreement. To make a more useful comparison, she answered the group-assignment prompt again. This time she gave an example of what two teammates had said and explained how they reached a decision. She wrote down that change as evidence of clearer idea development. Her next goal was to see whether she could use the same level of detail on a new interview question.",
        question("Why was the original comparison difficult to interpret?", ["The recordings were the same length.", "The talks differed in topic familiarity and task demands.", "The first recording had no audible speech."], 1, "两个题目的熟悉程度和任务要求不同。 A more relaxed voice could partly reflect the easier topic."),
        question("Which detail did Hana use as evidence of progress?", ["She spoke on an entirely different topic.", "She finished a week earlier than expected.", "She described what teammates said and how the decision was reached."], 2, "同一题目里增加了具体的对话和解决过程。 The clearer explanation provides a comparable detail."),
        question("What does her next goal test?", ["Whether the improvement transfers to another question", "Whether she remembers both recordings word for word", "Whether classmates always agree with her opinions"], 0, "她想看新题上能否同样具体。 A new interview prompt tests transfer.")),
      exercise("One last rehearsal",
        "For our last rehearsal, I suggest you take the student role first and let me ask the interview questions. Choose between the two topics I offer, and I'll keep the questions on the one you select. I'll move to the next question if we're running out of time. After the interview, I'll tell you one result from your example that I could remember and one place where I lost the connection. Then we'll swap roles. We should keep that discussion until after the timer stops, because interrupting every answer would make the practice feel quite different from the test.",
        question("What determines the topic of the interview?", ["The student's choice between two options", "A new choice before every question", "The feedback given after the first answer"], 0, "学生从两项中选一，问题围绕所选主题。 The questions stay on the chosen topic."),
        question("What feedback will the partner give?", ["An estimated official language score", "One memorable result and one unclear connection", "A complete written transcript of every answer"], 1, "反馈包含听得明白的结果和没跟上的衔接。 The partner identifies a remembered result and a lost link."),
        question("Why is the feedback delayed?", ["The student must first rewrite the entire talk.", "The interviewer needs to listen to another student.", "Repeated interruptions would change the nature of the rehearsal."], 2, "每答一句就打断会改变模拟体验。 Waiting preserves the flow of the timed practice.")),
      "compare like with like", "To compare like with like, I tried the same prompt again before moving on to a new topic.")
  ];
})();
